<?php
/** AXISCNC owned template editors; isolated from historical Starter editors. */
namespace AxisCNC\Suite;
defined('ABSPATH') || exit;

function field(string $name, string $label, string $type='text', array $extra=[]): array {
    return array_merge(['key'=>'field_axis_suite_'.$name,'name'=>$name,'label'=>$label,'type'=>$type,'instructions'=>'Edit this page only. Empty optional content is hidden on the website.','required'=>0,'show_in_rest'=>true],$extra);
}
function sub(string $scope,string $name,string $label,string $type='text',array $extra=[]):array {
    return array_merge(field($name,$label,$type),['key'=>'field_axis_suite_'.$scope.'_'.$name],$extra);
}
function tab(string $id,string $label):array{return field('tab_'.$id,$label,'tab',['placement'=>'top']);}
function image(string $scope,string $name='image',string $label='Image'):array{return sub($scope,$name,$label,'image',['return_format'=>'id','preview_size'=>'medium','instructions'=>'Select or upload in the WordPress Media Library. Use original images or labelled AI concepts.']);}
function rich(string $name,string $label):array{return field($name,$label,'wysiwyg',['tabs'=>'all','toolbar'=>'full','media_upload'=>1]);}
function repeat(string $name,string $label,array $children,int $max=20):array{return field($name,$label,'repeater',['layout'=>'block','sub_fields'=>$children,'max'=>$max,'button_label'=>'Add item','instructions'=>'Drag to reorder. Add or delete rows. Only valid rows appear; deleting the final row hides the whole module.']);}
function pairs(string $name,string $label,string $first='Title',string $second='Description',int $max=12):array{return repeat($name,$label,[sub($name,'title',$first),sub($name,'body',$second,'textarea',['rows'=>3])],$max);}
function clone_fields(string $name,array $names):array{return field('clone_'.$name,'','clone',['clone'=>array_map(static fn($n)=>'field_axis_suite_'.$n,$names),'display'=>'seamless','layout'=>'block','prefix_label'=>0,'prefix_name'=>0]);}
function register():void{
