),sub('design','body','Design guidance','textarea')],12),tab('evidence','07 · Evidence & quality'),field('axis_suite_case_heading','Optional verified case heading'),rich('axis_suite_case_body','Verified case narrative'),field('axis_suite_case_image','Verified case image','image',['return_format'=>'id','instructions'=>'Only a real permitted project image. Leave empty when no verified case is available.']),field('axis_suite_quality_heading','Quality heading'),rich('axis_suite_quality_body','Quality and handover scope'),pairs('axis_suite_quality_checks','Quality checkpoints','Checkpoint','What to agree',8),field('axis_suite_gallery','Supporting image gallery','gallery',['return_format'=>'id','preview_size'=>'medium','instructions'=>'AI images remain labelled as concepts. Do not use them as factory or testing evidence.']),tab('faq','08 · FAQ'),pairs('axis_suite_faq','Frequently asked questions','Question','Answer',16)];
