add_action('acf/init',__NAMESPACE__.'\\register',30);

/** Keep old homepage editors off the new assigned template, retaining all values. */
add_filter('acf/load_field_group',static function(array $group):array{
    // Native location conditions switch the complete editor, including Add New
    // and the admin's asynchronous Template selector. No saved values are removed.
    if(in_array($group['key']??'',['group_home_content','group_starter_home','group_axis_capability','group_axis_project_support'],true))foreach($group['location']as&$rules)$rules[]=['param'=>'post_template','operator'=>'!=','value'=>'page-templates/axis-home.php'];
    return $group;
});
